// Tronix.AI: Healthcare SaaS | AI Clinic Operations, Pilot stage, raising INR 3.5 Cr.
// Cheque is a FLOOR: an investor whose MINIMUM cheque exceeds 3.5 Cr cannot participate,
// because the whole round cannot absorb it. No upper limit - co-investment handles that.
const RAISE = 3.5;
function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
if (trk.length < 200) { throw new Error('ABORT: tracker only ' + trk.length + ' rows - truncated'); }

// Tronix is brand new, but check the tracker anyway in case it was shared outside the pipeline
const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}
const trkSeen = {};
for (const r of trk) {
  for (const c of cDeals) {
    for (const d of s(r[c]).split(/[,;\n]/)) { if (nz(d).indexOf('tronix') >= 0) { trkSeen[nz(r[cInv])] = true; } }
  }
}
const pipeSeen = {};
for (const p of pipe) { if (nz(p.startup).indexOf('tronix') >= 0) { pipeSeen[nz(p.investor)] = true; } }

// smallest cheque an investor writes, in INR Cr
function minCr(txt) {
  const t = s(txt).replace(/,/g, '');
  if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*(?:-|to|–)?\s*([\d.]+)?\s*M/i);
  if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i);
  if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i);
  if (m) { return parseFloat(m[1]) / 100; }
  return null;
}

const out = [];
for (const r of inv) {
  const name = s(r.investor);
  if (!name) { continue; }
  if (s(r.do_not_contact).toLowerCase() === 'yes') { continue; }
  const k = nz(name);
  if (pipeSeen[k] || trkSeen[k]) { continue; }

  const sec = s(r.sector).toLowerCase();
  const stg = s(r.stage).toLowerCase();

  const agnostic = /agnostic/.test(sec);
  const health = /health|medtech|bio|clinic|pharma|life science/.test(sec);
  const softw = /saas|b2b|enterprise|software|\bai\b|deeptech|deep tech|tech/.test(sec);
  if (!agnostic && !health && !softw) { continue; }

  // Pilot stage sits at pre-seed/seed. Exclude funds that only start at Series A or later.
  const earlyOK = stg === '' || /pre-?seed|seed|early|agnostic|pre seed/.test(stg);
  const lateOnly = /series a onwards|series c|pre ipo|post series b/.test(stg);
  if (!earlyOK || lateOnly) { continue; }

  const floor = minCr(r.cheque_inr_cr);
  if (floor !== null && floor > RAISE) { continue; }

  // Same rubric as every prior run: sector 40 / stage 30 / cheque 30.
  let secPts;
  if (agnostic) { secPts = (health || softw) ? 28 : 20; }
  else if (health) { secPts = 40; }
  else { secPts = 34; }

  const score = secPts + 30 + (floor === null ? 18 : 30);
  if (score < 70) { continue; }
  out.push({ name: name, email: s(r.email), score: score, floor: floor });
}

out.sort(function (a, b) { return b.score - a.score || a.name.localeCompare(b.name); });
if (out.length === 0) { throw new Error('ABORT: no matches for Tronix.AI'); }
if (out.length > 120) { throw new Error('ABORT: ' + out.length + ' matches exceeds guard of 120'); }

let maxN = 0;
for (const p of pipe) {
  const id = s(p.deal_id);
  if (id.charAt(0) === 'D') { const n = parseInt(id.slice(1), 10); if (!isNaN(n) && n > maxN) { maxN = n; } }
}
function weekdays(n, y, m, d) {
  const a = []; const dt = new Date(Date.UTC(y, m - 1, d));
  while (a.length < n) { const w = dt.getUTCDay(); if (w !== 0 && w !== 6) { a.push(dt.toISOString().slice(0, 10)); } dt.setUTCDate(dt.getUTCDate() + 1); }
  return a;
}
const days = weekdays(Math.ceil(out.length / 2) + 1, 2026, 9, 10);

let n = maxN;
return out.map(function (o, i) {
  n++;
  let pad = String(n);
  while (pad.length < 5) { pad = '0' + pad; }
  return { json: { deal_id: 'D' + pad, startup: 'Tronix.AI', owner: 'Aditya', investor: o.name,
    email: o.email, cc: '', priority: o.score, deal_shared: 'No', next_action: 'Initial',
    next_due: days[Math.floor(i / 2)],
    notes: (o.score >= 85 ? 'Very High' : (o.score >= 70 ? 'High' : 'Moderate')) + ' match (' + o.score + ') - Tronix.AI added 2026-09-09' } };
});
